import itertools

def simulate(seq, k):
    n = len(seq)
    visited = set()
    while True:
        state = tuple(seq)
        if state in visited:
            return False  # Stuck in a cycle without reaching the goal
        visited.add(state)

        # Check if goal reached: at most one boundary
        boundaries = 0
        for i in range(n - 1):
            if seq[i] != seq[i+1]:
                boundaries += 1
        if boundaries <= 1:
            return True

        # Perform operation
        # k-th coin is at index k-1
        coin = seq[k-1]
        left = k - 1
        while left > 0 and seq[left-1] == coin:
            left -= 1
        right = k - 1
        while right < n - 1 and seq[right+1] == coin:
            right += 1

        block = seq[left : right + 1]
        rest = seq[0 : left] + seq[right + 1 :]
        seq = block + rest

def check_k(n, k):
    # Coins: n As, n Cs
    # Total coins = 2n
    # Generate all permutations
    for p in itertools.permutations('A' * n + 'C' * n):
        if not simulate(list(p), k):
            return False
    return True

for n in range(1, 7):
    print(f"n={n}: ", end="")
    results = []
    for k in range(1, 2*n + 1):
        if check_k(n, k):
            results.append(k)
    print(results)

